    test_cases = [
        ("user_001", "approve"),
        ("user_002", "reject"),
        ("user_003", "pending")
    ]
    for user_id, decision in test_cases:
        logger.log_decision(user_id, decision)
    summary = logger.get_summary()
    print(f"Total Decisions Logged: {summary['total_records']}")
    for record in summary["unique_decisions"]:
        print(record)

