    return {f"input_{i}": str(result_data)}
async def main():
    sample_inputs = [
        {"type": "string", "value": "hello_world"},
        {"type": "integer", "value": 50},
        {"type": "integer", "value": 200},
    ]
    loop = asyncio.get_event_loop()
    tasks = []
    results_map = {}
    for idx, item in enumerate(sample_inputs):
        if item["type"] == "string":
            task = process_branch_a(item["value"])
        elif item["type"] == "integer":
            val = int(item["value"])
            task = process_branch_b(val)
        tasks.append(task)
    results_map.update(await asyncio.gather(*tasks))
    print(results_map)
if __name__ == '__main__':
    main()

import asyncio
from typing import List, Dict, Any
async def process_branch_a(data: str) -> Dict[str, Any]:
    return {"branch": "A", "status": "completed", "data_length": len(data)}
async def process_branch_b(data: int) -> Dict[str, Any]:
    if data > 100:
        result = f"Value {data} exceeds threshold."
    else:
        result = f"Value {data} is within range."
    return {"branch": "B", "status": "completed", "message": result}
async def process_branch_c(data: float) -> Dict[str, Any]:
    processed_value = round(data * 2.5, 4)
    return {"branch": "C", "status": "completed", "calculated": processed_value}
async def main():
    tasks: List[Dict[str, Any]] = [
        {
            "input_type": "string",
            "value": "Hello World",
            "handler": process_branch_a,
        },
        {
            "input_type": "int",
            "value": 150,
            "handler": process_branch_b,
        },
        {
            "input_type": "float",
            "value": 42.876,
            "handler": process_branch_c,
        },
    ]
    results = await asyncio.gather(*[task["handler"](task["value"]) for task in tasks])
    print(results)
if __name__ == '__main__':
    main()

import asyncio
from typing import List, Dict, Any
async def process_branch_a(data: str) -> Dict[str, Any]:
    return {"branch": "A", "status": "completed", "input": data}
async def process_branch_b(data: int) -> Dict[str, Any]:
    result = f"Calculated value for {data}"
    return {"branch": "B", "status": "success", "result": result}
async def main():
    tasks: List[Dict[str, Any]] = [
        {"type": "text", "value": "hello_world"},
        {"type": "number", "value": 42},
        {"type": "flag", "value": True}
    ]
    results: Dict[int, Dict[str, Any]] = {}
    for idx, task in enumerate(tasks):
        if not isinstance(task["value"], str) and task["type"] == "text":
            continue
        branch_map = {
            1: process_branch_a,
            2: process_branch_b
        }
        selected_func = None
        if isinstance(task["value"], str):
            selected_func = lambda x=task["value"]: process_branch_a(x)
        elif task["type"] == "number":
            selected_func = lambda x=task["value"]: process_branch_b(x)
        if selected_func:
            results[idx] = await asyncio.create_task(selected_func())
    print("Processing complete. Results:")
    for idx, res in results.items():
        print(f"Task {idx}: {res}")
if __name__ == '__main__':
    asyncio.run(main())
